// Typed runtime client for the ScholarLoop UI API (docs/openapi/openapi.yaml).
// The schemas are generated by `npm run api:gen` (openapi-typescript) and committed
// at src/api/openapi.gen.d.ts. This file is the thin fetch layer on top.
//
// Requests use same-origin relative paths (/api/*) so the Vite dev server (or the
// production reverse proxy) routes them - a remote browser preview never calls
// localhost. In dev, /api is proxied to the Prism mock of the spec
// (see vite.config.ts and `npm run mock`).
//
// Token discipline: the bearer token lives in module memory only. It is never
// written to localStorage or cookies, so closing the tab ends the session.

import type { components } from './openapi.gen'

export type ValidationFieldError = {
  loc: string
  msg: string
  type: string
}

export type HealthResponse = components['schemas']['HealthResponse']
export type ConfigResponse = components['schemas']['ConfigResponse']
export type ContractListResponse = components['schemas']['ContractListResponse']
export type UserView = components['schemas']['UserView']
export type TokenResponse = components['schemas']['TokenResponse']
export type AccountView = components['schemas']['AccountView']
export type AccountCreate = components['schemas']['AccountCreate']
export type AccountPatch = components['schemas']['AccountPatch']
export type DeleteResult = components['schemas']['DeleteResult']
export type AccountTestResult = components['schemas']['AccountTestResult']
export type BindingView = components['schemas']['BindingView']
export type BindingPut = components['schemas']['BindingPut']
export type ProjectList = components['schemas']['ProjectList']
export type ProjectView = components['schemas']['ProjectView']
export type ProjectCreate = components['schemas']['ProjectCreate']
export type RunView = components['schemas']['RunView']
export type RunSummary = components['schemas']['RunSummary']
export type RunList = components['schemas']['RunList']
export type RunCreate = components['schemas']['RunCreate']
