const metaEnv = (import.meta as { env?: Record<string, string | undefined> }).env ?? {}
const API_BASE = (metaEnv.VITE_API_BASE_URL ?? '').replace(/\/+$/, '')

let accessToken: string | null = null
const tokenListeners = new Set<(token: string | null) => void>()
const unauthorizedListeners = new Set<() => void>()

export function getAccessToken(): string | null {
  return accessToken
}

export function setAccessToken(token: string | null): void {
  accessToken = token
  for (const listener of tokenListeners) listener(token)
}

export function subscribeToken(listener: (token: string | null) => void): () => void {
  tokenListeners.add(listener)
  return () => {
    tokenListeners.delete(listener)
  }
}

export function subscribeUnauthorized(listener: () => void): () => void {
  unauthorizedListeners.add(listener)
  return () => {
    unauthorizedListeners.delete(listener)
  }
}

export class ApiError extends Error {
  readonly status: number
  readonly code: string | undefined
  readonly context: Record<string, unknown> | undefined
  readonly fieldErrors: ValidationFieldError[]

  constructor(
    message: string,
    status: number,
    code: string | undefined = undefined,
    context: Record<string, unknown> | undefined = undefined,
  ) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.code = code
    this.context = context
    this.fieldErrors = parseFieldErrors(context)
  }
}

function parseFieldErrors(context?: Record<string, unknown>): ValidationFieldError[] {
  if (!context || !Array.isArray(context.errors)) return []
  const out: ValidationFieldError[] = []
  for (const item of context.errors) {
    if (item && typeof item === 'object') {
      const rec = item as Record<string, unknown>
      if (typeof rec.loc === 'string' && typeof rec.msg === 'string') {
        out.push({
          loc: rec.loc,
          msg: rec.msg,
          type: typeof rec.type === 'string' ? rec.type : 'value_error',
        })
      }
    }
  }
  return out
}

function extractDetail(
  payload: unknown,
  status: number,
): { message: string; code: string | undefined; context: Record<string, unknown> | undefined } {
  if (payload && typeof payload === 'object') {
    const record = payload as Record<string, unknown>
    const candidate =
      record.error && typeof record.error === 'object'
        ? (record.error as Record<string, unknown>)
        : record.detail && typeof record.detail === 'object'
          ? (record.detail as Record<string, unknown>)
          : null
    if (candidate) {
      const message =
        typeof candidate.message === 'string' ? candidate.message : `request failed (${status})`
      const code = typeof candidate.code === 'string' ? candidate.code : undefined
      const context =
        candidate.context && typeof candidate.context === 'object' && !Array.isArray(candidate.context)
          ? (candidate.context as Record<string, unknown>)
          : undefined
      return { message, code, context }
    }
    if (typeof record.detail === 'string') return { message: record.detail, code: undefined, context: undefined }
  }
  return { message: `request failed (${status})`, code: undefined, context: undefined }
}

interface RequestOptions {
  method?: string
  headers?: Record<string, string>
  body?: unknown
  signal?: AbortSignal | undefined
  /** Send the in-memory bearer token. Defaults to true; false for auth endpoints. */
  auth?: boolean
}

async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
  const { method, headers: incomingHeaders, body, signal, auth = true } = options
  const headers = new Headers(incomingHeaders)
  headers.set('Accept', 'application/json')

  const token = auth ? accessToken : null
  if (token) headers.set('Authorization', `Bearer ${token}`)

  const init: RequestInit = { headers }
  if (method !== undefined) init.method = method
  if (signal) init.signal = signal
  if (body !== undefined) {
    if (typeof body === 'string') {
      init.body = body
    } else {
      headers.set('Content-Type', 'application/json')
      init.body = JSON.stringify(body)
    }
  }

  const response = await fetch(`${API_BASE}${path}`, init)
  const text = await response.text()
  let payload: unknown = undefined
  if (text.length > 0) {
    try {
      payload = JSON.parse(text)
    } catch {
      payload = undefined
    }
  }

  if (!response.ok) {
    if (response.status === 401 && token) {
      for (const listener of unauthorizedListeners) listener()
    }
    const detail = extractDetail(payload, response.status)
    throw new ApiError(detail.message, response.status, detail.code, detail.context)
  }

  return payload as T
}

function queryString(params?: Record<string, string | number | boolean | null | undefined>): string {
  const qs = new URLSearchParams()
  if (params) {
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined && value !== null) qs.set(key, String(value))
    }
  }
  const serialized = qs.toString()
  return serialized ? `?${serialized}` : ''
}

