export async function listAccounts(signal?: AbortSignal): Promise<AccountView[]> {
  return request('/api/accounts', { auth: true, signal })
}

export async function createAccount(payload: AccountCreate): Promise<AccountView> {
  return request('/api/accounts', { method: 'POST', body: payload })
}

export async function getAccount(
  accountId: string,
  signal?: AbortSignal,
): Promise<AccountView> {
  return request(`/api/accounts/${encodeURIComponent(accountId)}`, { auth: true, signal })
}

export async function patchAccount(accountId: string, payload: AccountPatch): Promise<AccountView> {
  return request(`/api/accounts/${encodeURIComponent(accountId)}`, {
    method: 'PATCH',
    body: payload,
    auth: true,
  })
}

export interface DeleteAccountOptions {
  replacementAccountId?: string | null | undefined
  disableRoles?: boolean | null | undefined
}

export async function deleteAccount(
  accountId: string,
  options: DeleteAccountOptions = {},
): Promise<DeleteResult> {
  const url = `/api/accounts/${encodeURIComponent(accountId)}${queryString({
    replacement_account_id: options.replacementAccountId,
    disable_roles: options.disableRoles,
  })}`
  return request(url, { method: 'DELETE', auth: true })
}

export async function testAccount(accountId: string): Promise<AccountTestResult> {
  return request(`/api/accounts/${encodeURIComponent(accountId)}/test`, {
    method: 'POST',
    auth: true,
  })
}

// ---------------------------------------------------------------------------
// Agent bindings
// ---------------------------------------------------------------------------

export async function getAgentBinding(
  role: string,
  signal?: AbortSignal,
): Promise<BindingView | null> {
  try {
    return await request(`/api/agents/${encodeURIComponent(role)}/binding`, { auth: true, signal })
  } catch (err) {
    if (err instanceof ApiError && err.status === 404) return null
    throw err
  }
}

export async function putAgentBinding(role: string, payload: BindingPut): Promise<BindingView> {
  return request(`/api/agents/${encodeURIComponent(role)}/binding`, {
    method: 'PUT',
    body: payload,
    auth: true,
  })
}

// ---------------------------------------------------------------------------
// SSE (Server-Sent Events) URL builder for /api/runs/{run_id}/events
// ---------------------------------------------------------------------------

export function runEventsUrl(
  runId: string,
  options: { after?: number | null | undefined; once?: boolean | null | undefined } = {},
): string {
  return (
    `/api/runs/${encodeURIComponent(runId)}/events` +
    queryString({
      after: options.after ?? undefined,
      once: options.once ?? undefined,
    })
  )
}
